const action = $json.action || 'list';
// Favourites are keyed by userId (stable per household); sessionId kept as a
// fallback for older callers. Note: staticData resets if this workflow is edited.
const userId = $json.userId || $json.sessionId || 'household';
const item = ($json.item || '').trim().toLowerCase();
const store = ($json.store || '').trim();

const staticData = $getWorkflowStaticData('global');
if (!staticData.favourites) staticData.favourites = {};
if (!staticData.favourites[userId]) staticData.favourites[userId] = [];

const favs = staticData.favourites[userId];
let response = '';

if (action === 'save') {
  if (!item || item.length < 2) {
    response = 'Could not save: item name was empty.';
  } else {
    const existing = favs.find(function(f) { return f.name === item; });
    if (existing) {
      if (store) existing.store = store;
      response = 'Already saved "' + item + '"' + (store ? ' (updated preferred store to ' + store + ')' : '') + '.';
    } else {
      const entry = { name: item, addedAt: new Date().toISOString() };
      if (store) entry.store = store;
      favs.push(entry);
      response = 'Saved "' + item + '" to favourites' + (store ? ' (preferred store: ' + store + ')' : '') + '.';
    }
  }
} else if (action === 'remove') {
  // Exact match first so removing "milk" doesn't take "milk chocolate" with it;
  // fall back to substring match only when nothing matched exactly.
  const before = favs.length;
  let next = favs.filter(function(f) { return f.name !== item; });
  if (next.length === before) {
    next = favs.filter(function(f) { return f.name.indexOf(item) === -1; });
  }
  staticData.favourites[userId] = next;
  const removed = before - next.length;
  response = removed > 0
    ? 'Removed ' + removed + ' favourite(s) matching "' + item + '".'
    : 'No favourites matched "' + item + '".';
} else if (action === 'list') {
  if (favs.length === 0) {
    response = 'No favourites saved yet.';
  } else {
    response = 'Saved favourites:\n' + favs.map(function(f) {
      return '- ' + f.name + (f.store ? ' (prefers ' + f.store + ')' : '');
    }).join('\n');
  }
} else if (action === 'list_json') {
  // Machine-readable list for the weekly digest workflow.
  response = JSON.stringify(favs);
} else {
  response = 'Unknown action: ' + action;
}

return [{ json: { response: response } }];
